#: How long a prepared template stays usable for polling without a re-send.
TEMPLATE_MAX_AGE_SECONDS = 7 * 24 * 3600

#: Media kinds the phone page can pick or upload, with their extensions.
MEDIA_EXTENSIONS = {
    "image": (".png", ".jpg", ".jpeg", ".webp", ".bmp", ".gif", ".avif", ".tiff"),
    "video": (".mp4", ".webm", ".mov", ".mkv", ".avi", ".m4v", ".gif"),
    "audio": (".mp3", ".wav", ".flac", ".ogg", ".m4a", ".aac", ".opus"),
}

#: Media types the phone page can edit as plain values.
EDITABLE_TYPES = {"INT", "FLOAT", "STRING", "BOOLEAN", "COMBO", "combo", "INT:", "FLOAT:"}

#: Preview files that may sit next to a LoRA, in priority order.
#:
#: Downloaders and managers put a same-named image beside the weights, either
#: with the plain extension or a ".preview" suffix; some video LoRAs ship an mp4
#: instead.
LORA_PREVIEW_SUFFIXES = (
    ".preview.png", ".preview.jpg", ".preview.jpeg", ".preview.webp",
    ".png", ".jpg", ".jpeg", ".webp", ".gif",
    ".mp4", ".webm",
)

#: Model files a dropdown can point at (only those have previews).
MODEL_FILE_EXTENSIONS = (".safetensors", ".ckpt", ".pt", ".pth", ".bin", ".gguf")


def _loras_roots() -> list[str]:
    """Every directory ComfyUI reads LoRAs from."""
    try:
        import folder_paths

        roots = folder_paths.get_folder_paths("loras")
    except Exception:
        return []
    return [root for root in (roots or []) if root and os.path.isdir(root)]


def _find_lora_preview(name: str) -> str | None:
    """The preview image of one LoRA, or ``None`` when it has none.

    *name* is the dropdown value, which is the LoRA's path relative to a loras
    directory (``Qwen2.1/图生图/a.safetensors``, backslashes included on
    Windows). Anything that escapes the loras directories is refused: the phone
    is a web page and this route serves files from disk.
    """
    relative = str(name or "").strip().replace("\\", "/").strip("/")
    if not relative or ".." in relative.split("/"):
        return None
    parts = [part for part in relative.split("/") if part]
    if not parts:
        return None
    for root in _loras_roots():
        root_real = os.path.normcase(os.path.realpath(root))
        candidate = os.path.realpath(os.path.join(root, *parts))
        # realpath() resolves symlinks, so compare against the resolved root.
        if os.path.normcase(candidate) != root_real and not os.path.normcase(
            candidate
        ).startswith(root_real + os.sep):
            continue
        if not os.path.isfile(candidate):
            continue
        base = os.path.splitext(candidate)[0]
        for suffix in LORA_PREVIEW_SUFFIXES:
            preview = base + suffix
            if os.path.isfile(preview):
                return preview
    return None


def _list_media(root: str, allowed: tuple[str, ...], limit: int = 400) -> list[dict[str, Any]]:
    """List media files in *root* (recursive, newest first)."""
    found: list[tuple[float, dict[str, Any]]] = []
    for base, _dirs, files in os.walk(root):
        for name in files:
            ext = os.path.splitext(name)[1].lower()
            if ext not in allowed:
                continue
            path = os.path.join(base, name)
            try:
                stat = os.stat(path)
            except OSError:
                continue
            relative = os.path.relpath(path, root).replace(os.sep, "/")
            found.append(
                (
                    stat.st_mtime,
                    {
                        "name": relative,
                        "size": stat.st_size,
                        "modified": int(stat.st_mtime),
                    },
                )
            )
    found.sort(key=lambda item: item[0], reverse=True)
    return [entry for _stamp, entry in found[:limit]]


def _media_directory(source: str) -> str | None:
    """The folder behind ``input`` / ``output``, as the phone names them."""
    try:
        if str(source).lower() == "output":
            return folder_paths.get_output_directory()
        return folder_paths.get_input_directory()
    except Exception:
        return None


def _resolve_media(source: str, name: str) -> str | None:
    """Absolute path of one listed media file, refusing anything outside it."""
    root = _media_directory(source)
    if not root:
        return None
    relative = str(name or "").replace("\\", "/").strip("/")
    if not relative or ".." in relative.split("/"):
        return None
    root_real = os.path.realpath(root)
    candidate = os.path.realpath(os.path.join(root, *relative.split("/")))
    if candidate != root_real and not candidate.startswith(root_real + os.sep):
        return None
    return candidate if os.path.isfile(candidate) else None


def delete_media(source: str, name: str) -> bool:
    """Remove one file from the input or output folder.

    The same guard as every other media path: only a file that resolves inside
    the chosen directory can go, and it must actually be there. Returns
    ``False`` when there was nothing to delete.
    """
    path = _resolve_media(source, name)
    if not path:
        return False
    try:
        os.remove(path)
        return True
    except OSError:
        return False


def _png_text_chunks(path: str) -> dict[str, str]:
    """Read the text chunks of a PNG without any extra dependency.

    ComfyUI's SaveImage stores the generation parameters there (``parameters``)
    alongside the API prompt and the UI workflow, which is how the phone can
    offer to copy what produced a picture.
    """
    chunks: dict[str, str] = {}
    with open(path, "rb") as handle:
        if handle.read(8) != b"\x89PNG\r\n\x1a\n":
            return chunks
        while True:
            header = handle.read(8)
            if len(header) < 8:
                break
            length = struct.unpack(">I", header[:4])[0]
            kind = header[4:8]
            data = handle.read(length)
            handle.read(4)  # CRC
            if kind == b"IEND":
                break
            if kind == b"tEXt":
                key, _, value = data.partition(b"\x00")
                chunks[key.decode("latin-1")] = value.decode("utf-8", "replace")
            elif kind == b"zTXt":
                key, _, rest = data.partition(b"\x00")
                try:
                    chunks[key.decode("latin-1")] = zlib.decompress(
                        rest[1:]
                    ).decode("utf-8", "replace")
                except Exception:
                    pass
            elif kind == b"iTXt":
                key, _, rest = data.partition(b"\x00")
                if len(rest) < 2:
                    continue
                compressed = rest[0] == 1
                rest = rest[2:]
                _language, _, rest = rest.partition(b"\x00")
                _translated, _, text = rest.partition(b"\x00")
                if compressed:
                    try:
                        text = zlib.decompress(text)
                    except Exception:
                        continue
                chunks[key.decode("latin-1")] = text.decode("utf-8", "replace")
    return chunks


def _prompt_from_api_json(raw: str) -> str:
    """Join the text inputs of a stored API prompt, for images without one."""
    try:
        data = json.loads(raw)
    except (TypeError, ValueError):
        return ""
    if not isinstance(data, dict):
        return ""
    texts: list[str] = []
    for node in data.values():
        inputs = node.get("inputs") if isinstance(node, dict) else None
        if not isinstance(inputs, dict):
            continue
        text = inputs.get("text")
        if isinstance(text, str) and text.strip() and text not in texts:
            texts.append(text.strip())
    return "\n".join(texts)


def _read_image_prompt(path: str) -> str:
    """The generation prompt embedded in a saved image, or an empty string.

    ``parameters`` is the human-readable form ComfyUI writes next to the PNG;
    when only the API prompt is present, its text inputs are collected instead.
    """
    try:
        chunks = _png_text_chunks(path)
    except OSError:
        return ""
    text = (chunks.get("parameters") or "").strip()
    if text:
        return text
    return _prompt_from_api_json(chunks.get("prompt") or "")


#: Longest edge of a thumbnail, and how many of them to keep on disk.
THUMB_MAX_EDGE = 320
THUMB_QUALITY = 72
THUMB_CACHE_LIMIT = 4000


def _thumb_dir() -> str | None:
    """Where generated thumbnails live, next to the template store."""
    base = _store_path()
    if not base:
        return None
    directory = os.path.join(os.path.dirname(base), "thumbs")
    try:
        os.makedirs(directory, exist_ok=True)
    except OSError:
        return None
    return directory


def _thumb_path(source: str, name: str, stamp: int, size: int) -> str | None:
    """Cache file for one thumbnail.

    The key carries the mtime and size, so overwriting a file in place yields a
    different name and the phone can never show a stale picture.
    """
    root = _media_directory(source)
    directory = _thumb_dir()
    if not root or not directory:
        return None
    key = "|".join(
        [
            os.path.realpath(root),
            str(name),
            str(stamp),
            str(size),
            str(THUMB_MAX_EDGE),
        ]
    )
    digest = hashlib.sha1(key.encode("utf-8")).hexdigest()
    return os.path.join(directory, digest + ".webp")


def _render_thumb(source_path: str, target: str) -> bool:
    """Write a small webp beside *target*, returning False when impossible."""
    try:
        from PIL import Image, ImageOps
    except Exception:  # pragma: no cover - ComfyUI always ships Pillow
        return False
    temp = target + ".tmp"
    try:
        with Image.open(source_path) as image:
            # Animated files: the first frame is the thumbnail.
            image.seek(0)
            image = ImageOps.exif_transpose(image)
            image.thumbnail((THUMB_MAX_EDGE, THUMB_MAX_EDGE))
            if image.mode not in ("RGB", "RGBA"):
                image = image.convert("RGBA" if "A" in image.getbands() else "RGB")
            image.save(temp, format="WEBP", quality=THUMB_QUALITY, method=3)
        os.replace(temp, target)
    except Exception:
        try:
            os.remove(temp)
        except OSError:
            pass
        return False
    _prune_thumbs(os.path.dirname(target))
    return True


def _prune_thumbs(directory: str) -> None:
    """Keep the thumbnail cache bounded: drop the oldest fifth past the cap."""
    try:
        entries = [
            os.path.join(directory, item)
            for item in os.listdir(directory)
            if item.endswith(".webp")
        ]
    except OSError:
        return
    if len(entries) <= THUMB_CACHE_LIMIT:
        return
    try:
        entries.sort(key=lambda path: os.stat(path).st_mtime)
    except OSError:
        return
    for path in entries[: max(1, len(entries) // 5)]:
        try:
            os.remove(path)
        except OSError:
            pass


#: How many templates to keep on disk. Each one holds a full prompt plus the
#: UI graph, so an unbounded file would grow without limit.
TEMPLATE_STORE_LIMIT = 60

#: Debounce between disk writes; the canvas watcher can re-push repeatedly.
TEMPLATE_SAVE_DELAY = 2.0


def _store_path() -> str | None:
    """Where prepared templates are cached outside of memory."""
    try:
        import folder_paths

        base = folder_paths.get_user_directory()
    except Exception:
        return None
    if not base:
        return None
    return os.path.join(base, "QQ_ComfyUI_Tools", "mobile_templates.json")


class MobileState:
    """Registry of prepared templates, keyed by workflow path.

    Templates are kept in memory and mirrored to disk. Without the mirror a
    ComfyUI restart empties the phone's pipeline picker, and every workflow has
    to be re-opened on the desktop just to press the button again.
    """

    def __init__(self) -> None:
        self.templates: dict[str, dict[str, Any]] = {}
        # Workflows the phone asked to be prepared, and how it went. Only the
        # editor can expand a workflow, so the phone leaves a request and the
        # editor picks it up. Kept in memory: a request is only useful while
        # an editor is watching.
        self.requests: dict[str, dict[str, Any]] = {}
        self.lock = asyncio.Lock()
        self._save_timer: Any = None
        self._dirty = False

    def request_prepare(
        self, workflow_key: str, payload: dict[str, Any]
    ) -> dict[str, Any]:
        """Remember that the phone wants this workflow prepared."""
        record = {
            "workflow": workflow_key,
            "path": payload.get("path") or "",
            "title": payload.get("title") or workflow_key,
            "folder": payload.get("folder") or "",
            "state": "pending",
            "error": "",
            "since": time.time(),
        }
        self.requests[workflow_key] = record
        return record

    def pending_requests(self) -> list[dict[str, Any]]:
        """Requests the editor still has to work on."""
        return [
            record
            for record in self.requests.values()
            if record.get("state") == "pending"
        ]

    def settle_request(
        self, workflow_key: str, ok: bool, error: str = ""
    ) -> dict[str, Any] | None:
        """Record how a preparation went.

        A stored template means the workflow is ready, so a request is settled
        as done there; a failure is reported by the editor.
        """
        record = self.requests.get(workflow_key)
        if record is None:
            return None
        record["state"] = "done" if ok else "failed"
        record["error"] = "" if ok else str(error or "")
        return record

    def _next_updated(self) -> float:
        """A timestamp strictly newer than every stored template.

        ``time.time()`` on Windows only ticks about every 15.6 ms, so two
        templates prepared back to back can carry the exact same timestamp and
        ``get(None)`` then returns whichever one ``max`` happens to see first
        instead of the one prepared last. Nudging past the newest record keeps
        "the most recently prepared workflow" well defined.
        """
        now = time.time()
        if self.templates:
            newest = max(
                float(record.get("updated") or 0) for record in self.templates.values()
            )
            if now <= newest:
                now = newest + 1e-6
        return now

    def put(self, workflow_key: str, payload: dict[str, Any]) -> dict[str, Any]:
        record = {
            "workflow": workflow_key,
            "title": payload.get("title") or workflow_key,
            "prompt": payload.get("prompt") or {},
            "parameters": payload.get("parameters") or [],
            "outputs": payload.get("outputs") or [],
            # One prompt per combination of group-switch states, keyed the same
            # way the extension keys them.
            "variants": payload.get("variants") or {},
            # Which phone parameter drives which switch.
            "switches": payload.get("switches") or [],
            # Folder inside the workflow directory, so the phone can group the
            # library the way the editor's sidebar does.
            "folder": payload.get("folder") or "",
            # The UI graph, sent back on submission as extra_pnginfo.workflow.
            # Without it ShowText and other nodes that look the workflow up by
            # node id fail, and saved PNGs lose their embedded workflow.
            "graph": payload.get("graph") or {},
            "updated": self._next_updated(),
        }
        self.templates[workflow_key] = record
        self._schedule_save()
        return record

    def get(self, workflow_key: str | None) -> dict[str, Any] | None:
        if workflow_key:
            record = self.templates.get(workflow_key)
            if record and time.time() - record["updated"] <= TEMPLATE_MAX_AGE_SECONDS:
                return record
            return None
        if not self.templates:
            return None
        newest = max(self.templates.values(), key=lambda item: item["updated"])
        if time.time() - newest["updated"] > TEMPLATE_MAX_AGE_SECONDS:
            return None
        return newest

    def prune(self) -> None:
        cutoff = time.time() - TEMPLATE_MAX_AGE_SECONDS
        stale = [key for key, value in self.templates.items() if value["updated"] < cutoff]
        for key in stale:
            self.templates.pop(key, None)
        if stale:
            self._schedule_save()

    # -- persistence -----------------------------------------------------
    def load(self) -> int:
        """Restore templates from disk. Returns how many were loaded."""
        path = _store_path()
        if not path or not os.path.exists(path):
            return 0
        try:
            with open(path, encoding="utf-8") as handle:
                data = json.load(handle)
        except (OSError, ValueError):
            return 0
        records = data.get("templates") if isinstance(data, dict) else None
        if not isinstance(records, dict):
            return 0

        cutoff = time.time() - TEMPLATE_MAX_AGE_SECONDS
        restored = 0
        for key, record in records.items():
            if not isinstance(record, dict):
                continue
            if float(record.get("updated") or 0) < cutoff:
                continue
            if not isinstance(record.get("prompt"), dict):
                continue
            self.templates[str(key)] = record
            restored += 1
        return restored

    def _schedule_save(self) -> None:
        """Coalesce writes so a burst of edits produces one file write."""
        self._dirty = True
        if self._save_timer is not None:
            return
        try:
            loop = asyncio.get_running_loop()
        except RuntimeError:
            # No loop (import time, tests): write directly.
            self.save_now()
            return
        self._save_timer = loop.call_later(TEMPLATE_SAVE_DELAY, self._save_from_timer)

    def _save_from_timer(self) -> None:
        self._save_timer = None
        if self._dirty:
            self.save_now()

    def save_now(self) -> None:
        """Write the cache to disk, newest templates first."""
        path = _store_path()
        if not path:
            return
        self._dirty = False
        ordered = sorted(
            self.templates.items(),
            key=lambda item: item[1].get("updated") or 0,
            reverse=True,
        )[:TEMPLATE_STORE_LIMIT]
        payload = {
            "version": 1,
            "templates": {key: record for key, record in ordered},
        }
        try:
            os.makedirs(os.path.dirname(path), exist_ok=True)
            temp = f"{path}.tmp"
            with open(temp, "w", encoding="utf-8") as handle:
                json.dump(payload, handle, ensure_ascii=False)
            # Replace atomically so a crash cannot leave a truncated cache.
            os.replace(temp, path)
        except OSError:
            # A read-only user directory is not fatal: the feature still works
            # from memory for this session.
            pass


STATE = MobileState()


def _normalise_parameters(raw: Any) -> list[dict[str, Any]]:
    """Keep the parameter schema the phone form consumes."""
    parameters: list[dict[str, Any]] = []
    for entry in raw or []:
        if not isinstance(entry, dict):
            continue
        targets = [
            [str(target[0]), str(target[1])]
            for target in entry.get("targets") or []
            if isinstance(target, (list, tuple)) and len(target) == 2
        ]
        parameters.append(
            {
                "key": str(entry.get("key") or entry.get("name") or ""),
                "name": str(entry.get("name") or ""),
                "label": str(entry.get("label") or entry.get("name") or ""),
                "type": str(entry.get("type") or "STRING"),
                "value": entry.get("value"),
                "targets": targets,
                "options": entry.get("options") or None,
                "min": entry.get("min"),
                "max": entry.get("max"),
                "step": entry.get("step"),
                "multiline": bool(entry.get("multiline")),
                "group": entry.get("group"),
                "hidden": bool(entry.get("hidden")),
                # "image" / "video" / "audio" turns this field into a media
                # picker with upload; the value written is the file name.
                "media": entry.get("media") or None,
                # QQ-多媒体加载 keeps its selection in one JSON string.
                "mediaState": bool(entry.get("mediaState")),
                "multiple": bool(entry.get("multiple")),
                # Came from a QQ-多值输入 node. The phone groups those by node
                # and folds them when a workflow carries several.
                "multi": bool(entry.get("multi")),
            }
        )
    return parameters


def _variant_key(pairs: list[tuple[str, str]]) -> str:
    """Name of one combination of switch states, matching the extension."""
    return ";".join(sorted(f"{tag}={value}" for tag, value in pairs))


def _select_variant(
    record: dict[str, Any], values: dict[str, Any]
) -> dict[str, Any]:
    """The prompt that matches the switch states the phone chose.

    A QQ-魔术贴 bypasses its whole group while it says 绕过, and a bypassed
    node is missing from the prompt altogether. So the prompt for 绕过 and the
    prompt for 启用 are different graphs, not the same graph with one value
    changed. The extension pre-builds one prompt per state; this picks the
    one the phone's values ask for.
    """
    variants = record.get("variants") or {}
    if not variants:
        return record["prompt"]
    switches = record.get("switches") or []
    if not switches:
        return record["prompt"]

    pairs: list[tuple[str, str]] = []
    for switch in switches:
        tag = str(switch.get("tag") or "")
        if not tag:
            continue
        value = values.get(str(switch.get("key") or ""), switch.get("default"))
        pairs.append((tag, "" if value is None else str(value)))
    if not pairs:
        return record["prompt"]
    return variants.get(_variant_key(pairs)) or record["prompt"]


def apply_parameter_values(
    prompt: dict[str, Any], parameters: list[dict[str, Any]], values: dict[str, Any]
) -> tuple[dict[str, Any], list[str]]:
    """Write submitted *values* into a copy of *prompt*.

    Returns ``(prompt, warnings)``. Unknown keys and parameters without targets
    are reported as warnings instead of raised, so a single stale field cannot
    break the whole submission.
    """
    updated = copy.deepcopy(prompt)
    warnings: list[str] = []
    by_key = {parameter["key"]: parameter for parameter in parameters}

    for key, value in (values or {}).items():
        parameter = by_key.get(key)
        if parameter is None:
            warnings.append(f"未知参数: {key}")
            continue
        targets = parameter.get("targets") or []
        if not targets:
            warnings.append(f"参数 {parameter.get('label') or key} 没有可写入的目标")
            continue
        serialised = _serialise_media_value(parameter, value)
        if serialised is _UNSERIALISABLE:
            warnings.append(f"参数 {parameter.get('label') or key} 的值无效，已跳过")
            continue
        for exec_id, input_name in targets:
            node = updated.get(exec_id)
            if node is None:
                warnings.append(f"节点 {exec_id} 不在模板中，已跳过 {key}")
                continue
            node.setdefault("inputs", {})[input_name] = serialised
    return updated, warnings


_UNSERIALISABLE = object()

#: Node that can only see a painted layer through a file, never through a link.
MASKED_LOADER_NODE = "LoadImage"

_ANNOTATION_PATTERN = re.compile(r"\s*\[(?:input|output|temp)\]\s*$", re.IGNORECASE)


def prepare_masked_load_images(prompt: dict[str, Any]) -> int:
    """Point ``LoadImage`` nodes with a painted layer at a copy for this run.

    The phone submits a prompt prepared when the toolbar button was pressed, so
    a picture chosen then would never see a layer painted afterwards — and a
    copy made then may have been swept since. Both are avoided by writing the
    copy here, at submit time, and only in the prompt that is about to run.

    Returns how many values were rewritten.
    """
    changed = 0
    for entry in prompt.values():
        if not isinstance(entry, dict):
            continue
        if str(entry.get("class_type") or "") != MASKED_LOADER_NODE:
            continue
        inputs = entry.get("inputs")
        if not isinstance(inputs, dict):
            continue
        value = inputs.get("image")
        if not isinstance(value, str) or not value:
            continue
        name = _ANNOTATION_PATTERN.sub("", value).strip()
        if not name or not paint_mask.mask_exists(name):
            continue
        reference = paint_mask.write_masked_copy(name)
        if not reference:
            continue
        inputs["image"] = reference
        changed += 1
    return changed


#: Media state keys, matching QQ-多媒体加载's accepted shape.
MEDIA_STATE_KEYS = {"image": "images", "video": "videos", "audio": "audios"}


def _serialise_media_value(parameter: dict[str, Any], value: Any) -> Any:
    """Turn a phone-side value into what the node expects.

    ``QQ-多媒体加载`` reads one JSON string holding ``images`` / ``audios`` /
    ``videos`` lists, so a list of chosen file names has to be encoded. Plain
    pickers such as ``LoadImage`` take the file name string as-is.
    """
    if not parameter.get("mediaState"):
        return value

    if isinstance(value, str):
        # Already encoded, or a single name that still has to be wrapped.
        text = value.strip()
        if text.startswith("{"):
            try:
                json.loads(text)
                return text
            except ValueError:
                return _UNSERIALISABLE
        names = [text] if text else []
        kind = parameter.get("media") or "image"
        key = MEDIA_STATE_KEYS.get(kind, "images")
        return json.dumps({key: names}, ensure_ascii=False)

    if isinstance(value, list):
        names = [str(item) for item in value if str(item or "").strip()]
        kind = parameter.get("media") or "image"
        key = MEDIA_STATE_KEYS.get(kind, "images")
        return json.dumps({key: names}, ensure_ascii=False)

    if isinstance(value, dict):
        return json.dumps(value, ensure_ascii=False)

    return _UNSERIALISABLE


def collect_outputs(prompt: dict[str, Any]) -> list[dict[str, str]]:
    """Pick output-node media from a prompt without querying the server."""
    return []


#: Media collections ComfyUI output nodes report in history.
OUTPUT_KINDS = ("images", "videos", "gifs", "audio")


def extract_media(history_entry: dict[str, Any]) -> list[dict[str, Any]]:
    """Flatten one ``/history`` entry into a list of displayable media."""
    media: list[dict[str, Any]] = []
    for node_id, payload in (history_entry.get("outputs") or {}).items():
        if not isinstance(payload, dict):
            continue
        for kind in OUTPUT_KINDS:
            for item in payload.get(kind) or []:
                if not isinstance(item, dict) or not item.get("filename"):
                    continue
                media.append(
                    {
                        "node": str(node_id),
                        "kind": kind,
                        "filename": item.get("filename"),
                        "subfolder": item.get("subfolder") or "",
                        "type": item.get("type") or "output",
                        "format": item.get("format"),
                        "metadata": item.get("metadata") or {},
                    }
                )
        for text in payload.get("text") or []:
            if isinstance(text, str) and text.strip():
                media.append({"node": str(node_id), "kind": "text", "text": text})
    return media


def media_url(item: dict[str, Any]) -> str:
    """Build the ``/view`` query for one media entry."""
    query = {
        "filename": item.get("filename", ""),
        "subfolder": item.get("subfolder", ""),
        "type": item.get("type", "output"),
    }
    if item.get("format"):
        query["format"] = item["format"]
    return "/view?" + urlencode(query)


async def _fetch_json(url: str) -> Any:
    async with aiohttp.ClientSession() as session:
        async with session.get(url) as response:
            if response.status >= 400:
                return None
            return await response.json(content_type=None)


def _web_dir() -> str:
    return os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "web")


def _local_base(request: Any) -> str:
    """Base URL for the plugin's own requests *to this same server*.

    ComfyUI sits behind a reverse proxy in the common deployment (Caddy with
    basic auth, nginx, a tunnel). ``request.url`` there is the public address,
    so a self-request built from it goes out to the internet, comes back
    through the proxy, and — because server-to-server calls carry no
    credentials — is challenged with 401. That is the "asked to log in twice"
    symptom: the browser authenticated, then the plugin called itself
    anonymously.

    Calling the loopback address keeps these internal requests off the proxy.
    When the server was started with ``--listen`` on a specific interface only,
    loopback may not be bound, so the bind address is used as a fallback.
    """
    instance = PromptServer.instance
    port = getattr(instance, "port", None) or 8188
    address = str(getattr(instance, "address", "") or "").strip()
    # 0.0.0.0 / :: mean "all interfaces", where loopback works.
    if address in ("", "0.0.0.0", "::", "[::]"):
        return f"http://127.0.0.1:{port}"
    if address in ("localhost", "::1"):
        return f"http://127.0.0.1:{port}"
    return f"http://{address}:{port}"


def _lan_url(port: int) -> str:
    """Best guess at the address a phone should use to reach this machine.

    Opens a UDP socket towards a public address to learn which local interface
    the OS would route through. No packet is sent, so this works offline and
    costs nothing; an unroutable network simply yields an empty string.
    """
    import socket

    try:
        with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as probe:
            probe.settimeout(0.2)
            probe.connect(("8.8.8.8", 80))
            ip = probe.getsockname()[0]
    except OSError:
        return ""
    if not ip or ip.startswith("127."):
        return ""
    return f"http://{ip}:{port}/qq_mobile/"


def _scan_workflows(root: str, limit: int = 500) -> list[dict[str, Any]]:
    """List every saved workflow under *root*, including subfolders.

    Returns the relative path (what the userdata API expects), the display
    name, the folder it lives in, and the workflow's own ``id`` — the phone
    keys templates by that id, so listing files and matching templates needs
    it.
    """
    entries: list[dict[str, Any]] = []
    if not root or not os.path.isdir(root):
        return entries
    for base, dirs, files in os.walk(root):
        dirs[:] = [name for name in dirs if not name.startswith(".")]
        for name in files:
            # Hidden files include the sidebar's own ".index" metadata.
            if name.startswith(".") or not name.lower().endswith(".json"):
                continue
            path = os.path.join(base, name)
            relative = os.path.relpath(path, root).replace(os.sep, "/")
            try:
                with open(path, encoding="utf-8") as handle:
                    data = json.load(handle)
            except (OSError, ValueError):
                continue
            if not isinstance(data, dict):
                continue
            nodes = data.get("nodes") or []
            # A workflow without nodes is a stub, not a pipeline.
            if not nodes:
                continue
            entries.append(
                {
                    "path": relative,
                    "name": os.path.splitext(name)[0],
                    "folder": os.path.dirname(relative),
                    "id": data.get("id"),
                    "nodes": len(nodes),
                    "updated": int(os.path.getmtime(path)),
                }
            )
    entries.sort(key=lambda item: (item["folder"], item["name"].lower()))
    return entries[:limit]


def _register_routes() -> None:
    try:
        from aiohttp import web  # noqa: F401
        from server import PromptServer  # noqa: F401
    except Exception:
        return
    server = getattr(PromptServer, "instance", None)
    if server is None or getattr(server, "_qq_mobile_routes", False):
        return

    mobile_page = os.path.join(_web_dir(), "mobile.html")

    @server.routes.get("/qq_mobile/")
    async def qq_mobile_page(request):
        if not os.path.exists(mobile_page):
            return web.json_response({"error": "mobile.html 缺失"}, status=404)
        return web.FileResponse(mobile_page, headers={"Cache-Control": "no-cache"})

    @server.routes.post("/qq_mobile/upload")
    async def qq_mobile_upload(request):
        """Accept a phone upload and hand it to ComfyUI's input directory.

        Forwarded to the official ``/upload/image`` endpoint over loopback so
        the plugin keeps one upload path (naming, deduplication, the input
        folder rules) instead of writing files itself. A proxy in front of
        ComfyUI is bypassed for the same reason as the other internal calls.
        """
        try:
            form = await request.post()
        except Exception:
            return web.json_response({"error": "invalid upload"}, status=400)

        field = form.get("image") or form.get("file")
        if field is None or not getattr(field, "file", None):
            return web.json_response({"error": "缺少文件"}, status=400)

        filename = str(getattr(field, "filename", "") or "upload.bin")
        payload = field.file.read()

        data = aiohttp.FormData()
        data.add_field(
            "image",
            payload,
            filename=filename,
            content_type=getattr(field, "content_type", None) or "application/octet-stream",
        )
        # "input" keeps everything in the directory ComfyUI loaders can read.
        data.add_field("type", "input")
        overwrite = str(form.get("overwrite") or "false").lower()
        data.add_field("overwrite", overwrite)

        url = f"{_local_base(request)}/upload/image"
        try:
            async with aiohttp.ClientSession() as session:
                async with session.post(url, data=data) as response:
                    body = await response.json(content_type=None)
                    status = response.status
        except Exception as exc:  # pragma: no cover - defensive
            return web.json_response({"error": f"上传失败: {exc}"}, status=502)

        if status >= 400:
            return web.json_response(
                {"error": (body or {}).get("error") or "上传被拒绝"}, status=status
            )
        return web.json_response(
            {
                "ok": True,
                "name": (body or {}).get("name"),
                "subfolder": (body or {}).get("subfolder") or "",
                "type": (body or {}).get("type") or "input",
            }
        )

    @server.routes.get("/qq_mobile/preview")
    async def qq_mobile_preview(request):
        """Serve the preview image that sits next to a LoRA file.

        The phone shows it while a dropdown row is being considered, so the
        user can tell 30 similarly named LoRAs apart before picking one.
        """
        try:
            path = _find_lora_preview(request.query.get("name") or "")
        except OSError:
            path = None
        if not path:
            return web.json_response({"error": "no preview"}, status=404)
        return web.FileResponse(
            path,
            headers={
                # A preview rarely changes; the phone re-opens the sheet often.
                "Cache-Control": "public, max-age=86400",
                "Content-Disposition": "inline",
            },
        )

    @server.routes.get("/qq_mobile/media")
    async def qq_mobile_media(request):
        """List media in ComfyUI's input or output directory.

        Newest first: the phone is usually picking what it just made. The page
        can flip the order without another request, so the timestamps travel
        with each entry.
        """
        kind = str(request.query.get("kind") or "image").strip()
        allowed = MEDIA_EXTENSIONS.get(kind)
        if allowed is None:
            return web.json_response({"error": f"未知媒体类型: {kind}"}, status=400)

        source = "output" if str(request.query.get("source")).lower() == "output" else "input"
        root = _media_directory(source)
        if not root:
            return web.json_response({"files": [], "source": source})
        try:
            entries = await asyncio.get_running_loop().run_in_executor(
                None, _list_media, root, allowed
            )
        except OSError as exc:
            return web.json_response({"error": str(exc)}, status=500)
        return web.json_response({"files": entries, "source": source})

    @server.routes.delete("/qq_mobile/media")
    async def qq_mobile_delete_media(request):
        """Delete one generated file the user removed on the results page.

        Only ever a file inside the chosen directory (see ``delete_media``),
        and never implicit: the phone asks with an explicit confirmation.
        """
        source = "output" if str(request.query.get("source")).lower() == "output" else "input"
        name = request.query.get("name") or request.query.get("filename") or ""
        removed = await asyncio.get_running_loop().run_in_executor(
            None, delete_media, source, name
        )
        if not removed:
            return web.json_response({"error": "找不到这个文件"}, status=404)
        return web.json_response({"ok": True, "deleted": name})

    @server.routes.get("/qq_mobile/thumb")
    async def qq_mobile_thumb(request):
        """A small webp preview of one media file.

        The list used to point `<img>` straight at ``/view``, i.e. the original
        picture: 51 requests and 284 MB for one open of a 331 file folder, none
        of it cacheable. This serves a 320px webp once, then answers from the
        disk cache with an immutable header, so a second open costs nothing.
        """
        source = "output" if str(request.query.get("source")).lower() == "output" else "input"
        name = request.query.get("filename") or ""
        path = _resolve_media(source, name)
        if not path:
            return web.json_response({"error": "找不到这个文件"}, status=404)
        try:
            stat = os.stat(path)
        except OSError:
            return web.json_response({"error": "找不到这个文件"}, status=404)

        target = _thumb_path(source, name, int(stat.st_mtime), int(stat.st_size))
        if not target:
            return web.json_response({"error": "缩略图不可用"}, status=404)
        if not os.path.isfile(target):
            made = await asyncio.get_running_loop().run_in_executor(
                None, _render_thumb, path, target
            )
            if not made:
                return web.json_response({"error": "无法生成缩略图"}, status=404)
        return web.FileResponse(
            target,
            headers={
                # The key already carries mtime and size, so the bytes at this
                # URL can never change.
                "Cache-Control": "public, max-age=31536000, immutable",
                "Content-Type": "image/webp",
            },
        )

    @server.routes.get("/qq_mobile/media-prompt")
    async def qq_mobile_media_prompt(request):
        """The generation prompt stored inside one saved image."""
        source = "output" if str(request.query.get("source")).lower() == "output" else "input"
        path = _resolve_media(source, request.query.get("filename") or "")
        if not path:
            return web.json_response({"error": "找不到这张图"}, status=404)
        try:
            prompt = await asyncio.get_running_loop().run_in_executor(
                None, _read_image_prompt, path
            )
        except OSError as exc:
            return web.json_response({"error": str(exc)}, status=500)
        return web.json_response({"prompt": prompt, "found": bool(prompt)})

    @server.routes.post("/qq_mobile/import-media")
    async def qq_mobile_import_media(request):
        """Copy an output file into input so a loader can use it.

        LoadImage and friends only read from the input directory, so picking
        something that was generated earlier would otherwise leave a value the
        node cannot open.
        """
        try:
            payload = await request.json()
        except Exception:
            return web.json_response({"error": "invalid JSON"}, status=400)
        name = str(payload.get("filename") or "").strip()
        path = _resolve_media("output", name)
        if not path:
            return web.json_response({"error": "找不到这个文件"}, status=404)
        target_root = _media_directory("input")
        if not target_root:
            return web.json_response({"error": "找不到 input 目录"}, status=500)

        relative = name.replace("\\", "/").strip("/")
        folder, _, base = relative.rpartition("/")
        wanted = os.path.join(target_root, *([folder] if folder else []), base)
        try:
            os.makedirs(os.path.dirname(wanted), exist_ok=True)
            if not os.path.isfile(wanted) or os.path.getsize(wanted) != os.path.getsize(path):
                await asyncio.get_running_loop().run_in_executor(
                    None, shutil.copy2, path, wanted
                )
        except OSError as exc:
            return web.json_response({"error": str(exc)}, status=500)
        return web.json_response(
            {"name": (f"{folder}/{base}" if folder else base), "copied": True}
        )

    @server.routes.get("/qq_mobile/mask")
    async def qq_mobile_get_mask(request):
        """The painted layer for one image, or 404 when it has none.

        Keyed by the image path, so the same picture shares one mask across the
        media loader, LoadImage and the phone.
        """
        filename = request.query.get("filename") or ""
        path = paint_mask.mask_path(filename)
        if not path or not os.path.isfile(path):
            return web.json_response({"mask": None}, status=404)
        return web.FileResponse(
            path,
            headers={"Cache-Control": "no-store", "Content-Type": "image/png"},
        )

    @server.routes.get("/qq_mobile/mask/state")
    async def qq_mobile_mask_state(request):
        """Which of the given images already have a painted mask.

        The phone asks once per form instead of probing every picture.
        """
        names = [item for item in (request.query.get("files") or "").split("\n") if item]
        return web.json_response(
            {
                "masks": {
                    name: bool(paint_mask.mask_exists(name))
                    for name in names
                }
            }
        )

    @server.routes.post("/qq_mobile/mask")
    async def qq_mobile_set_mask(request):
        """Store a painted mask (body: image filename + base64 PNG)."""
        try:
            payload = await request.json()
        except Exception:
            return web.json_response({"error": "invalid JSON"}, status=400)
        filename = str(payload.get("filename") or "").strip()
        if not filename:
            return web.json_response({"error": "filename is required"}, status=400)
        encoded = str(payload.get("png") or "")
        if not encoded:
            return web.json_response({"error": "png is required"}, status=400)
        if encoded.startswith("data:"):
            encoded = encoded.split(",", 1)[-1]
        try:
            raw = base64.b64decode(encoded, validate=True)
        except Exception:
            return web.json_response({"error": "png is not valid base64"}, status=400)
        stored = await asyncio.get_running_loop().run_in_executor(
            None, paint_mask.save_mask_png, filename, raw
        )
        if not stored:
            return web.json_response({"error": "无法保存遮罩"}, status=400)
        return web.json_response({"ok": True, "has_mask": True})

    @server.routes.post("/qq_mobile/mask/prepare")
    async def qq_mobile_prepare_masks(request):
        """Give LoadImage a file it can take a MASK from, for one run.

        A plain LoadImage reads its MASK from the PNG's alpha channel and its
        outputs are fixed by ``RETURN_TYPES``, so the only way in is a file that
        carries the layer. That file is worth nothing outside the run that uses
        it: the copies are written here, right before the prompt is submitted,
        into ``temp`` — and every run re-writes them, so they can never go
        stale. Nothing is written when a layer is painted.
        """
        try:
            payload = await request.json()
        except Exception:
            return web.json_response({"error": "invalid JSON"}, status=400)
        files = []
        for item in payload.get("files") or []:
            name = str(item or "").strip()
            if name and name not in files:
                files.append(name)
        loop = asyncio.get_running_loop()
        references = {}
        for name in files:
            if not paint_mask.mask_exists(name):
                continue
            reference = await loop.run_in_executor(
                None, paint_mask.write_masked_copy, name
            )
            if reference:
                references[name] = reference
        return web.json_response({"masks": references})

    @server.routes.delete("/qq_mobile/mask")
    async def qq_mobile_delete_mask(request):
        """Drop the painted layer for one image."""
        filename = request.query.get("filename") or ""
        removed = await asyncio.get_running_loop().run_in_executor(
            None, paint_mask.delete_mask, filename
        )
        # The copy still carries the old alpha, so it must not outlive the layer.
        await asyncio.get_running_loop().run_in_executor(
            None, paint_mask.clear_masked_copies, filename
        )
        return web.json_response({"ok": bool(removed)})

    @server.routes.get("/qq_mobile/reachability")
    async def qq_mobile_reachability(request):
        """Report whether a phone on the network could reach this server.

        Two things decide it, and the bind address alone is not enough:

        * If the page was opened through a non-loopback host, the user is
          already reaching ComfyUI over the network (directly or via a reverse
          proxy), so a phone can use the same address.
        * Otherwise ComfyUI is being viewed on the machine itself. Binding
          127.0.0.1 (the default without ``--listen``) then makes it
          unreachable from a phone, while a wildcard bind is reachable through
          the machine's LAN address, which is reported back so it can be typed
          on the phone.

        Firewalls and port forwarding cannot be verified from inside the
        server, so a network path problem still has to be diagnosed by hand.
        """
        instance = PromptServer.instance
        port = getattr(instance, "port", None) or 8188
        address = str(getattr(instance, "address", "") or "").strip()

        # Where the browser reached us: a reverse proxy reports its own host.
        host = str(request.host or "").split(":")[0].strip().lower()
        viewed_over_network = bool(host) and host not in (
            "127.0.0.1", "localhost", "::1", "[::1]",
        )

        lan_url = _lan_url(port)
        local_only = address in ("127.0.0.1", "localhost", "::1")

        if viewed_over_network:
            return web.json_response(
                {
                    "reachable": True,
                    "known": True,
                    "address": address or "0.0.0.0",
                    "port": port,
                    "via_proxy": True,
                    "suggested_url": "",
                    "hint": "",
                }
            )

        if local_only:
            return web.json_response(
                {
                    "reachable": False,
                    "known": True,
                    "address": address,
                    "port": port,
                    "suggested_url": "",
                    "hint": (
                        f"ComfyUI 只监听本机（{address}:{port}），手机连不上。"
                        "请用 --listen 0.0.0.0 重新启动。"
                    ),
                }
            )

        # Wildcard bind, viewed from this machine: reachable, but the phone
        # needs the LAN address rather than 127.0.0.1.
        return web.json_response(
            {
                "reachable": True,
                "known": True,
                "address": address or "0.0.0.0",
                "port": port,
                "suggested_url": lan_url,
                "hint": (
                    f"手机请访问 {lan_url}" if lan_url
                    else "手机请使用本机的局域网 IP 访问"
                ),
            }
        )

    @server.routes.get("/qq_mobile/workflows")
    async def qq_mobile_workflows(request):
        """Every workflow the editor has saved, so the phone can list the
        whole library instead of only what was prepared already."""
        try:
            import folder_paths

            root = os.path.join(
                folder_paths.get_user_directory(), "default", "workflows"
            )
        except Exception:
            return web.json_response({"workflows": []})
        try:
            entries = await asyncio.get_running_loop().run_in_executor(
                None, _scan_workflows, root
            )
        except OSError as exc:
            return web.json_response({"error": str(exc)}, status=500)
        return web.json_response({"workflows": entries})

    @server.routes.get("/qq_mobile/state")
    async def qq_mobile_state(request):
        STATE.prune()
        records = [
            {
                "workflow": record["workflow"],
                "title": record["title"],
                "parameters": len(record["parameters"]),
                "folder": record.get("folder") or "",
                "graph_nodes": len((record.get("graph") or {}).get("nodes") or []),
                "updated": record["updated"],
            }
            for record in STATE.templates.values()
        ]
        return web.json_response({"templates": records})

    @server.routes.post("/qq_mobile/template")
    async def qq_mobile_template(request):
        try:
            payload = await request.json()
        except Exception:
            return web.json_response({"error": "invalid JSON"}, status=400)
        workflow_key = str(payload.get("workflow") or "").strip()
        if not workflow_key:
            return web.json_response({"error": "workflow is required"}, status=400)
        prompt = payload.get("prompt")
        if not isinstance(prompt, dict) or not prompt:
            return web.json_response({"error": "prompt is required"}, status=400)

        parameters = _normalise_parameters(payload.get("parameters"))
        graph = payload.get("graph")
        # Every field put() reads has to be forwarded here; a missed key is
        # silently stored as its default (this bit the graph and the folder).
        record = STATE.put(
            workflow_key,
            {
                "title": payload.get("title"),
                "folder": payload.get("folder"),
                "prompt": prompt,
                "parameters": parameters,
                "outputs": payload.get("outputs") or [],
                # One prompt per combination of group-switch states, keyed the
                # same way the extension keys them.
                "variants": payload.get("variants") or {},
                # Which phone parameter drives which switch.
                "switches": payload.get("switches") or [],
                "graph": graph if isinstance(graph, dict) else {},
            },
        )
        # A stored template means the workflow is ready, so a preparation the
        # phone asked for is done.
        STATE.settle_request(workflow_key, True)
        return web.json_response(
            {
                "ok": True,
                "workflow": record["workflow"],
                "parameters": len(record["parameters"]),
                "nodes": len(record["prompt"]),
                "graph_nodes": len((record.get("graph") or {}).get("nodes") or []),
            }
        )

    @server.routes.post("/qq_mobile/prepare")
    async def qq_mobile_prepare(request):
        """The phone asks for a workflow to be prepared.

        Only a browser holding the real graph can expand a workflow, so the
        request waits for the editor to pick it up.
        """
        try:
            payload = await request.json()
        except Exception:
            return web.json_response({"error": "invalid JSON"}, status=400)
        workflow_key = str(payload.get("workflow") or "").strip()
        if not workflow_key:
            return web.json_response({"error": "workflow is required"}, status=400)
        record = STATE.request_prepare(workflow_key, payload)
        return web.json_response({"ok": True, "workflow": record["workflow"]})

    @server.routes.get("/qq_mobile/prepare")
    async def qq_mobile_get_prepare(request):
        """The editor polls for work; the phone polls for the outcome."""
        return web.json_response(
            {
                "requests": [
                    {
                        "workflow": record.get("workflow"),
                        "path": record.get("path") or "",
                        "title": record.get("title") or "",
                        "folder": record.get("folder") or "",
                        "state": record.get("state") or "pending",
                        "error": record.get("error") or "",
                    }
                    for record in STATE.requests.values()
                ]
            }
        )

    @server.routes.post("/qq_mobile/prepare-result")
    async def qq_mobile_prepare_result(request):
        """The editor reports how a preparation went."""
        try:
            payload = await request.json()
        except Exception:
            return web.json_response({"error": "invalid JSON"}, status=400)
        workflow_key = str(payload.get("workflow") or "").strip()
        if not workflow_key:
            return web.json_response({"error": "workflow is required"}, status=400)
        ok = bool(payload.get("ok"))
        record = STATE.settle_request(workflow_key, ok, payload.get("error") or "")
        if record is None:
            return web.json_response({"error": "no request"}, status=404)
        return web.json_response({"ok": True, "state": record["state"]})

    @server.routes.get("/qq_mobile/template")
    async def qq_mobile_get_template(request):
        STATE.prune()
        record = STATE.get(request.query.get("workflow"))
        if record is None:
            return web.json_response({"error": "no template"}, status=404)
        return web.json_response(
            {
                "workflow": record["workflow"],
                "title": record["title"],
                "parameters": record["parameters"],
                "outputs": record["outputs"],
                "folder": record.get("folder") or "",
                # Which phone parameter drives which group switch, so the page
                # can tell the user what a switch will turn on.
                "switches": record.get("switches") or [],
                "updated": record["updated"],
            }
        )

    @server.routes.post("/qq_mobile/prompt")
    async def qq_mobile_prompt(request):
        try:
            payload = await request.json()
        except Exception:
            return web.json_response({"error": "invalid JSON"}, status=400)

        record = STATE.get(payload.get("workflow"))
        if record is None:
            return web.json_response(
                {"error": "模板不存在，请在 ComfyUI 里重新点击手机界面按钮"}, status=404
            )

        prompt, warnings = apply_parameter_values(
            _select_variant(record, payload.get("values") or {}),
            record["parameters"],
            payload.get("values") or {},
        )
        # A LoadImage takes its MASK from the file, so a painted layer has to
        # travel as a copy — made here, for this run, into temp.
        try:
            prepare_masked_load_images(prompt)
        except Exception as exc:  # pragma: no cover - a layer must not block a run
            warnings.append(f"遮罩未生效: {exc}")
        client_id = str(payload.get("client_id") or uuid.uuid4())
        extra_data = build_extra_data(client_id, record.get("graph"))

        # Reuse the official submission path so validation, node replacements,
        # job bookkeeping and WebSocket events all behave exactly as usual.
        # Addressed at the loopback interface so a reverse proxy in front of
        # ComfyUI (and its auth) is not part of our own request path.
        url = f"{_local_base(request)}/prompt"
        headers = {"Content-Type": "application/json"}
        body: dict[str, Any] = {
            "prompt": prompt,
            "client_id": client_id,
            "extra_data": extra_data,
        }
        try:
            async with aiohttp.ClientSession() as session:
                async with session.post(
                    url,
                    data=json.dumps(body),
                    headers=headers,
                ) as response:
                    result = await response.json(content_type=None)
                    status = response.status
        except Exception as exc:  # pragma: no cover - defensive
            return web.json_response({"error": f"提交失败: {exc}"}, status=502)

        if status >= 400:
            return web.json_response(
                {
                    "error": (result or {}).get("error") or "提交被拒绝",
                    "node_errors": (result or {}).get("node_errors") or {},
                },
                status=status,
            )
        prompt_id = (result or {}).get("prompt_id", "")
        if prompt_id:
            SUBMITTED_AT[str(prompt_id)] = time.time()
            # Keep the map from growing during a long session.
            if len(SUBMITTED_AT) > 512:
                cutoff = time.time() - 3600
                for key in [k for k, v in SUBMITTED_AT.items() if v < cutoff]:
                    SUBMITTED_AT.pop(key, None)
        return web.json_response(
            {
                "ok": True,
                "prompt_id": prompt_id,
                "number": (body or {}).get("number"),
                "warnings": warnings,
            }
        )

    @server.routes.post("/qq_mobile/interrupt")
    async def qq_mobile_interrupt(request):
        """Cancel what this phone started.

        ``/interrupt`` only stops the prompt that is currently executing; a
        prompt still waiting in the queue has to be deleted from it, otherwise
        pressing 取消 while queued does nothing at all.
        """
        payload: dict[str, Any] = {}
        try:
            payload = await request.json()
        except Exception:
            payload = {}
        prompt_id = str(payload.get("prompt_id") or "").strip()
        base = _local_base(request)

        deleted = False
        if prompt_id:
            try:
                async with aiohttp.ClientSession() as session:
                    async with session.post(
                        f"{base}/queue", json={"delete": [prompt_id]}
                    ) as response:
                        deleted = response.status < 400
            except Exception:  # pragma: no cover - defensive
                deleted = False

        try:
            async with aiohttp.ClientSession() as session:
                async with session.post(f"{base}/interrupt") as response:
                    interrupted = response.status < 400
        except Exception as exc:  # pragma: no cover - defensive
            return web.json_response({"error": str(exc)}, status=500)
        return web.json_response(
            {"ok": interrupted or deleted, "deleted": deleted, "interrupted": interrupted}
        )

    @server.routes.get("/qq_mobile/jobs")
    async def qq_mobile_jobs(request):
        """Report the state of one prompt plus whatever media it produced.

        ``/api/jobs/{id}`` is the only endpoint that answers "what is this
        prompt doing" on its own: it checks history, then the running queue,
        then the pending queue, and reports ``in_progress`` / ``pending`` /
        ``completed`` / ``failed`` / ``cancelled``.

        Note that ``GET /prompt`` must NOT be used for this. In this ComfyUI
        version it returns only ``{"exec_info": {"queue_remaining": N}}`` — no
        ``queue_running`` / ``queue_pending`` arrays — so a prompt that is
        actively executing looks absent there and would be reported as lost
        mid-run.
        """
        prompt_id = str(request.query.get("prompt_id") or "").strip()
        base = _local_base(request)
        elapsed = _elapsed_since_submit(request, prompt_id)

        if not prompt_id:
            return web.json_response({"status": "idle", "media": []})

        job = await _fetch_json(f"{base}/api/jobs/{prompt_id}")
        if isinstance(job, dict) and job.get("status"):
            status = str(job["status"])
            payload: dict[str, Any] = {
                "prompt_id": prompt_id,
                "status": status,
                "media": [],
            }
            if status == "pending":
                payload["position"] = await _queue_position(base, prompt_id)
            if status in ("completed", "failed", "cancelled"):
                payload["completed"] = status == "completed"
                payload["media"] = extract_media(job)
                payload["execution_error"] = _execution_error(job)
            return web.json_response(payload)

        # Not known to the job API. That is either the brief moment between a
        # prompt leaving the queue and its history entry landing, or a prompt
        # the server genuinely never ran.
        if elapsed is not None and elapsed < SETTLE_SECONDS:
            return web.json_response(
                {"prompt_id": prompt_id, "status": "settling", "media": []}
            )
        return web.json_response(
            {"prompt_id": prompt_id, "status": "lost", "media": []}
        )

    server._qq_mobile_routes = True


async def _queue_position(base: str, prompt_id: str) -> int | None:
    """Zero-based position of a pending prompt, from the queue listing."""
    queue = await _fetch_json(f"{base}/queue")
    if not isinstance(queue, dict):
        return None
    for position, entry in enumerate(queue.get("queue_pending") or []):
        if _queue_entry_matches(entry, prompt_id):
            return position
    return None


def _execution_error(job: dict[str, Any]) -> str | None:
    """Best-effort message for a job that ended without output."""
    error = job.get("execution_error")
    if isinstance(error, dict):
        return str(error.get("exception_message") or error.get("message") or "")
    if isinstance(error, str) and error:
        return error
    return None


#: How long after submission a prompt may be absent from both the queue and
#: the history before it is treated as lost. ComfyUI writes history slightly
#: after the queue entry disappears, so polling too eagerly would otherwise
#: report a healthy job as cancelled.
SETTLE_SECONDS = 20


def build_extra_data(
    client_id: str, graph: dict[str, Any] | None
) -> dict[str, Any]:
    """Assemble ``extra_data`` the way the official frontend does.

    ``extra_pnginfo.workflow`` is not decoration: nodes with an
    ``EXTRA_PNGINFO`` hidden input read the UI graph to find themselves by node
    id (``ShowText`` rewrites its own ``widgets_values``), and ``SaveImage``
    embeds it so a saved file can be dropped back into ComfyUI. Submitting
    without it makes those nodes log "extra_pnginfo[0] is not a dict or missing
    'workflow' key" and silently strips the workflow from outputs.
    """
    extra: dict[str, Any] = {"client_id": client_id}
    if isinstance(graph, dict) and graph.get("nodes") is not None:
        extra["extra_pnginfo"] = {"workflow": graph}
        # A prompt carrying a graph is tagged with its workflow id so /api/jobs
        # and the history can group runs, matching frontend behaviour.
        workflow_id = graph.get("id")
        if isinstance(workflow_id, str) and workflow_id:
            extra["workflow_metadata"] = {"workflow_id": workflow_id}
    return extra

#: When each prompt was submitted by this page, for the settling window.
SUBMITTED_AT: dict[str, float] = {}


def _elapsed_since_submit(request: web.Request, prompt_id: str) -> float | None:
    """Seconds since this server submitted *prompt_id*, if it did."""
    if not prompt_id:
        return None
    stamp = SUBMITTED_AT.get(prompt_id)
    if stamp is None:
        return None
    return time.time() - stamp


def _queue_entry_matches(entry: Any, prompt_id: str) -> bool:
    """Check whether one ``/prompt`` queue entry belongs to *prompt_id*."""
    if not prompt_id:
        return False
    if isinstance(entry, (list, tuple)):
        return any(str(part) == prompt_id for part in entry[:4])
    if isinstance(entry, dict):
        return str(entry.get("prompt_id")) == prompt_id
    return False


_register_routes()

# Restore the template cache so the phone's pipeline picker survives a restart.
try:
    STATE.load()
except Exception:  # pragma: no cover - never block startup on the cache
    pass


__all__ = [
    "STATE",
    "MobileState",
    "apply_parameter_values",
    "expand_workflow",
]
